-- spool_gmlc_all_201cols.sql
-- Same SQL*Plus CSV/spool pattern, with all 201 columns explicitly listed.
-- Usage:
-- sqlplus -L "USER/PASSWORD@DB" @"spool_gmlc_all_201cols.sql" "C:\Temp\gmlc.csv" "20260710000000" "20260816000000"

SET VERIFY OFF
SET SQLBLANKLINES ON
SET MARKUP CSV ON DELIMITER , QUOTE ON
SET HEADING OFF
SET FEEDBACK OFF
SET TERMOUT OFF
SET ECHO OFF
SET TRIMSPOOL ON
SET PAGESIZE 0
SET LONG 1000000
SET LINESIZE 32767
SET ARRAYSIZE 5000

ALTER SESSION SET NLS_DATE_FORMAT = 'YYYY-MM-DD HH24:MI:SS';
ALTER SESSION SET NLS_TIMESTAMP_FORMAT = 'YYYY-MM-DD HH24:MI:SS.FF6';

SPOOL &1

PROMPT "ALLGNSSPOSDATA","ALLOCATES_ECGI_HEX","ALLOCATES_RESULT_CODE","ALLUTRANPOSDATA","CALLID","CALL_ANOMALY","CALL_BEGIN_TIME","CALL_BEGIN_TIME_UTC","CALL_BEGIN_TO_LOCATE_SEC","CALL_DATE","CALL_DATE_UTC","CALL_DURATION_SEC","CALL_END_TIME","CALL_END_TIME_UTC","CALL_LEVEL_P2_LOCATE","CALL_STRATEGY","CALL_TRIGGER","CALL_TYPE","CANCEL_CNT","CELL_FIPS_CODE","CELL_LATITUDE","CELL_LONGITUDE","CELL_TIME_ZONE","CI_MARKET","COMPLETE_CALL","CONFIDENCE","CONTACT_HDR","COUNTY","CTID","DATETIME","DATETIME_INS","DATETIME_UTC","DEFAULT_ROUTED_CALL","DISTCELL2PSAPXY_M","DISTCELL2XY_M","DISTXY2PSAPXY_M","ELS_AVAILABLE","ELS_USED","ENODEB_ID","ENV","ESINET_PROVIDER","ESPOSREQ_COUNT","ESPOSREQ_FIRST_NAME","ESPOSREQ_INITIAL_LOCATION_SOURCE","ESPOSREQ_LASTKNOWN_LOCATION_SOURCE","ESPOSREQ_LAST_NAME","ESPOSREQ_LOC_ALTITUDE","ESPOSREQ_LOC_ALTITUDE_UNCERT","ESPOSREQ_LOC_CONFIDENCE","ESPOSREQ_LOC_HORIZONTAL_UNCERT","ESPOSREQ_LOC_LATITUDE","ESPOSREQ_LOC_LONGITUDE","ESPOSREQ_LOC_POS_SOURCE","ESPOSREQ_LOC_SHAPE_TYPE","ESRD","ESRK","ESRK_SIPAUDIT","ESRN","EXCEPTION_FLAG","EXCEPTION_TYPE","FAILURE_SHORT_DR","FCC_PSAP_ID","FIRST_ESPOSREQ_TIMESTAMP","GMLC_VENDOR","HANDSET_TAC","HDR_TRID","HDV_AUD_HOST","HDV_CNT","HDV_ECGI","HDV_RESULT_CODE","IMEI","IMSI","IMSLTE_CURR_DIAMETER_HOST","IMSLTE_DIAMETER_CONNECTION","IMSLTE_DIAM_CONN","IMSLTE_HANDOVER_TIMESTAMP","IMSLTE_ORIG_DIAMETER_HOST","INPUT_FILE_NAME","INVITE_CNT","INVITE_ECGI_HEX","INVITE_TO_END_SEC","INV_RSP_AUD_HOST","LAST_ESPOSREQ_TIMESTAMP","LATITUDE","LBR_ATTEMPTED","LBR_PSAP_DIFF","LBR_SUCCESS","LOCATE_BEGIN_TIME_UTC","LOCATE_CNT","LOCATE_ECGI","LOCATE_ECGI_DEC","LOCATE_END_TIME_UTC","LOCATE_TIME_SEC","LOCATE_TO_CALL_END_SEC","LOCATION_FIRST_ALTITUDE","LOCATION_FIRST_ALTITUDE_UNCERT","LOCATION_FIRST_CONFIDENCE","LOCATION_FIRST_GNSS_POS_DATA","LOCATION_FIRST_HORIZONTAL_UNCE","LOCATION_FIRST_SHAPE_TYPE","LOCATION_FIRST_UTRAN_POS_DATA","LOCATION_LAST_CONFIDENCE","LOCATION_LAST_GNSS_POS_DATA","LOCATION_LAST_HORIZONTAL_UNCER","LOCATION_LAST_SHAPE_TYPE","LOCATION_LAST_UTRAN_POS_DATA","LONGITUDE","LRR_INVITE_DELTA_SEC","LRR_INVITE_STATUS","LSR_EXCLUDE_REASON","MARKET","MARKET_CLUSTER","MLI_CALL_ID","MLI_STATUS_CODE","MME_ID","MME_NAME","MME_PHYSICAL_VIRTUAL","MME_POOL_ID","MME_POOL_NAME","MME_VENDOR","MPR_DATE","MSC_E164","MSC_PC","MSISDN","NETWORK_TRAFFIC","NW_METHOD_USED","ORIG_AUD_HOST","ORIG_CNT","ORIG_RESULT_CODE","P2_FAILURE_SHORT","P2_LOCATE","P2_SUCCESS","PHASE","PLR_IMSI","PLR_PLA_AUD_HOST","PL_RESULT_CODE","POS_METHOD_USED","PSAPTN","PSAP_CBN","PSAP_FIPS_CODE","PSAP_ID","PSAP_NAME","PSAP_NAME_ESRK","PSAP_SIM_CALL","PSL_COUNT","PSL_FIRST_RESPONSE_TIME","PSL_FIRST_SENT_TIME","REGION","REL_AUD_HOST","REL_CNT","REL_ECGI_HEX","REL_RESULT_CODE","ROUTE_ESINET","ROUTE_ESZ","ROUTE_FALLBACK","ROUTE_LOCATION_POS_SOURCE","ROUTE_OUT_DIGITS","ROUTE_OUT_TYPE","ROUTE_PSAP_NAME","ROUTE_STATUS_GMLC","RTT_INFO","SECTOR_NAME","SETUP_ECGI_DEC","SETUP_ECGI_HEX","SHAPE_TYPE","SIGNALLING_TYPE","SIPCELL_TYPE","SIP_CTID","SIP_LINK_ID","SIP_ORIGINAL_CTID","SIP_RECEIVE_TIME","SIP_RESPONSE_TIME","SIP_SIP_METHOD","SIP_STATUS","SIP_SYSTEM_ID","SIP_URI","SIP_USERAGENT","SIP_VIA","SLR_ORIG_NODE","STATE","STR_CODE_1","STR_CODE_2","TAC","TAC_ROUTED_CALL","TEST_CALL","TIME_ON_LTE_SEC","UE_MAKE_ABBR","UE_MODEL","UMTS_PRESENCE","UNCERT_METERS","UNIQ911_CID","USED_IN_BIDSR","USED_IN_CSR","USED_IN_LSR","USER_TYPE","USID","VERTICAL_UNCERT","WDLS_ALTITUDE","WDLS_ALTITUDEUNCERTAINTY","Z_GENERATED","Z_RELAYED2PSAP"

SELECT
    ALLGNSSPOSDATA,
    ALLOCATES_ECGI_HEX,
    ALLOCATES_RESULT_CODE,
    ALLUTRANPOSDATA,
    CALLID,
    CALL_ANOMALY,
    CALL_BEGIN_TIME,
    CALL_BEGIN_TIME_UTC,
    CALL_BEGIN_TO_LOCATE_SEC,
    CALL_DATE,
    CALL_DATE_UTC,
    CALL_DURATION_SEC,
    CALL_END_TIME,
    CALL_END_TIME_UTC,
    CALL_LEVEL_P2_LOCATE,
    CALL_STRATEGY,
    CALL_TRIGGER,
    CALL_TYPE,
    CANCEL_CNT,
    CELL_FIPS_CODE,
    CELL_LATITUDE,
    CELL_LONGITUDE,
    CELL_TIME_ZONE,
    CI_MARKET,
    COMPLETE_CALL,
    CONFIDENCE,
    CONTACT_HDR,
    COUNTY,
    CTID,
    DATETIME,
    DATETIME_INS,
    DATETIME_UTC,
    DEFAULT_ROUTED_CALL,
    DISTCELL2PSAPXY_M,
    DISTCELL2XY_M,
    DISTXY2PSAPXY_M,
    ELS_AVAILABLE,
    ELS_USED,
    ENODEB_ID,
    ENV,
    ESINET_PROVIDER,
    ESPOSREQ_COUNT,
    ESPOSREQ_FIRST_NAME,
    ESPOSREQ_INITIAL_LOCATION_SOURCE,
    ESPOSREQ_LASTKNOWN_LOCATION_SOURCE,
    ESPOSREQ_LAST_NAME,
    ESPOSREQ_LOC_ALTITUDE,
    ESPOSREQ_LOC_ALTITUDE_UNCERT,
    ESPOSREQ_LOC_CONFIDENCE,
    ESPOSREQ_LOC_HORIZONTAL_UNCERT,
    ESPOSREQ_LOC_LATITUDE,
    ESPOSREQ_LOC_LONGITUDE,
    ESPOSREQ_LOC_POS_SOURCE,
    ESPOSREQ_LOC_SHAPE_TYPE,
    ESRD,
    ESRK,
    ESRK_SIPAUDIT,
    ESRN,
    EXCEPTION_FLAG,
    EXCEPTION_TYPE,
    FAILURE_SHORT_DR,
