    LBR_ATTEMPTED,
    LBR_PSAP_DIFF,
    LBR_SUCCESS,
    LOCATE_BEGIN_TIME_UTC,
    LOCATE_CNT,
    LOCATE_ECGI,
    LOCATE_ECGI_DEC,
    LOCATE_END_TIME_UTC,
    LOCATE_TIME_SEC,
    LOCATE_TO_CALL_END_SEC,
    LOCATION_FIRST_ALTITUDE,
    LOCATION_FIRST_ALTITUDE_UNCERT,
    LOCATION_FIRST_CONFIDENCE,
    LOCATION_FIRST_GNSS_POS_DATA,
    LOCATION_FIRST_HORIZONTAL_UNCE,
    LOCATION_FIRST_SHAPE_TYPE,
    LOCATION_FIRST_UTRAN_POS_DATA,
    LOCATION_LAST_CONFIDENCE,
    LOCATION_LAST_GNSS_POS_DATA,
    LOCATION_LAST_HORIZONTAL_UNCER,
    LOCATION_LAST_SHAPE_TYPE,
    LOCATION_LAST_UTRAN_POS_DATA,
    LONGITUDE,
    LRR_INVITE_DELTA_SEC,
    LRR_INVITE_STATUS,
    LSR_EXCLUDE_REASON,
    MARKET,
    MARKET_CLUSTER,
    MLI_CALL_ID,
    MLI_STATUS_CODE,
    MME_ID,
    MME_NAME,
    MME_PHYSICAL_VIRTUAL,
    MME_POOL_ID,
    MME_POOL_NAME,
    MME_VENDOR,
    MPR_DATE,
    MSC_E164,
    MSC_PC,
    MSISDN,
    NETWORK_TRAFFIC,
    NW_METHOD_USED,
    ORIG_AUD_HOST,
    ORIG_CNT,
    ORIG_RESULT_CODE,
    P2_FAILURE_SHORT,
    P2_LOCATE,
    P2_SUCCESS,
    PHASE,
    PLR_IMSI,
    PLR_PLA_AUD_HOST,
    PL_RESULT_CODE,
    POS_METHOD_USED,
    PSAPTN,
    PSAP_CBN,
    PSAP_FIPS_CODE,
    PSAP_ID,
    PSAP_NAME,
    PSAP_NAME_ESRK,
    PSAP_SIM_CALL,
    PSL_COUNT,
    PSL_FIRST_RESPONSE_TIME,
    PSL_FIRST_SENT_TIME,
    REGION,
    REL_AUD_HOST,
    REL_CNT,
