    RTT_INFO,
    SECTOR_NAME,
    SETUP_ECGI_DEC,
    SETUP_ECGI_HEX,
    SHAPE_TYPE,
    SIGNALLING_TYPE,
    SIPCELL_TYPE,
    SIP_CTID,
    SIP_LINK_ID,
    SIP_ORIGINAL_CTID,
    SIP_RECEIVE_TIME,
