    STR_CODE_1,
    STR_CODE_2,
    TAC,
    TAC_ROUTED_CALL,
    TEST_CALL,
    TIME_ON_LTE_SEC,
    UE_MAKE_ABBR,
    UE_MODEL,
    UMTS_PRESENCE,
    UNCERT_METERS,
    UNIQ911_CID,
    USED_IN_BIDSR,
    USED_IN_CSR,
    USED_IN_LSR,
    USER_TYPE,
    USID,
    VERTICAL_UNCERT,
    WDLS_ALTITUDE,
    WDLS_ALTITUDEUNCERTAINTY,
    Z_GENERATED,
    Z_RELAYED2PSAP
FROM WEST911.E911_LTE_MASTER_GMLC
WHERE DATETIME_UTC >= TO_TIMESTAMP('&2','YYYYMMDDHH24MISS')
  AND DATETIME_UTC <  TO_TIMESTAMP('&3','YYYYMMDDHH24MISS');

SPOOL OFF
EXIT
